@spec generators_spec  src=tests/specs/generators_spec.lua  loc=599  cases=42
@exercises generators (generators), tuning (tuning)
@surface   generators.parksNotes, generators.parkWindows, generators.continuousTargets, generators.destOf, generators.fieldsFor, generators.retarget, generators.fieldRange, tuning.findTemper, tuning.transposeStep, tuning.stepsBetween, generators.thinCurve

# Intent
  generators.lua: slide glide-in envelope.

# Helpers
  @fn expand(kind, hostRec, params, ctx)  @ 9-11
      -- Kinds run alone here, so the chain state equals the original: stream == host (the chain head).
  @fn slideCtx(nextNote, pbRangeCents)  @ 14-17
      -- A slide host (pitch 60) and a ctx supplying the next same-lane note + pb ceiling.
  @fn slideHost(detune)  @ 18-20
  @fn triangle()  @ 24-30
      -- A loop-closed triangle in the normalized domain (-1 .. +1 .. -1), one QN long.
  @fn pts(rows)  @ 34-40
      -- Curve points positionally: {ppq, val, shape?, tension?}; shape defaults to linear, the one kind
      -- thinCurve is allowed to drop.

# Cases
  @case 'slide glides in: flat hold, slur to the interval, re-centre at the window end'  [pure]  @ 47-58
  @case 'slide interval includes detune (the microtonal offset rides in detune, not pitch)'  [pure]  @ 62-66
  @case 'slide clamps the target to ctx.pbRangeCents (a pb can only bend so far)'  [pure]  @ 70-74
  @case 'slide.target='fixed' is a fixed-cents bend (cents demand, no next-note lookup)'  [pure]  @ 78-83
  @case 'slide.target='next' with no following note yields no delta (carrier untouched)'  [pure]  @ 87-91
  @case 'slide to a unison next note yields no delta (zero interval)'  [pure]  @ 95-99
  @case 'trill tiles the window from its start, alternating host pitch with the stepped note'  [pure]  @ 105-121
  @case 'trill carries host detune verbatim on the return (even) tiles'  [pure]  @ 125-132
  @case 'parksNotes is true for any note-dest kind, false for a continuous kind / husk'  [pure]  @ 138-143
  @case 'parkWindows emits an evType-tagged window per continuous/replace target (note discrete, cc, pb augment)'  [pure]  @ 147-162
  @case 'the ownership predicates ignore bypass: a bypassed chain still parks and still scopes its target'  [pure]  @ 166-176
  @case 'destOf falls back to the registry dest; a dest param overrides it'  [pure]  @ 182-187
  @case 'fieldsFor prepends a Dest row only where the kind can serve more than one target'  [pure]  @ 191-199
  @case 'retarget between dests of equal reference leaves the magnitudes alone'  [pure]  @ 203-208
  @case 'retarget rescales magnitudes by proportion of the dest reference'  [pure]  @ 212-218
  @case 'fieldRange spans both ways for a signed magnitude, one way for an unsigned one'  [pure]  @ 222-228
  @case 'retarget carries a signed magnitude across with its sign intact'  [pure]  @ 232-238
  @case 'parkWindows follows the dest param, not the registry (a retargeted pb kind parks cc)'  [pure]  @ 242-249
  @case 'sine on a cc dest tiles the window with extrema in cc steps, anchored 0 at both ends'  [pure]  @ 255-268
  @case 'velPattern cycles its percent pattern per distinct onset; a chord shares one step'  [pure]  @ 274-289
  @case 'velPattern walks onset order regardless of input order, clamping vel to 1..127'  [pure]  @ 293-303
  @case 'ostinato tracks the sounding pitch across the region, not just the first note'  [pure]  @ 309-321
  @case 'ostinato rests when no region note sounds at the gate onset'  [pure]  @ 325-334
  @case 'ostinato emits one gated note per sounding voice (a chord -> multiple lanes)'  [pure]  @ 338-349
  @case 'chord-stamp rebases the pattern chord onto each member; lane-1 note lands on the trigger'  [pure]  @ 355-378
  @case 'chord-stamp transposes by whole temper steps through ctx, not by raw pitch'  [pure]  @ 382-401
  @case 'chord-stamp fires a chord on every region member (all lanes are triggers)'  [pure]  @ 405-427
  @case 'chord-stamp with no lane-1 note in the pattern is inert (no root to rebase from)'  [pure]  @ 431-442
  @case 'lfo tiles the curve at 1/period QN, mapping each val by offset + scale, edges seeded'  [pure]  @ 448-465
  @case 'lfo maps norm in whatever units the dest counts in -- cents on pb'  [pure]  @ 469-478
  @case 'lfo does not clamp -- the body holds no dest knowledge, and the cc seat clamps'  [pure]  @ 482-491
  @case 'lfo with an empty or lengthless curve is inert (no delta)'  [pure]  @ 495-504
  @case 'thinCurve returns a degenerate curve verbatim -- endpoints are never candidates'  [pure]  @ 510-517
  @case 'thinCurve collapses a collinear linear run to its endpoints'  [pure]  @ 521-528
  @case 'thinCurve drops a spike whose vertical error only meets the tolerance'  [pure]  @ 532-536
  @case 'thinCurve keeps a spike whose vertical error exceeds the tolerance'  [pure]  @ 540-543
  @case 'thinCurve keeps a stepped run whole, collinear though its points are'  [pure]  @ 547-551
  @case 'thinCurve rides a curved point through with its tension intact'  [pure]  @ 555-561
  @case 'thinCurve lets a non-linear point pin its successor as well as itself'  [pure]  @ 565-570
  @case 'thinCurve treats a missing shape as non-linear -- under-thin over silently ramping'  [pure]  @ 574-578
  @case 'thinCurve keeps a stack of coincident points -- a zero-width span has no chord'  [pure]  @ 582-586
  @case 'thinCurve gives a dual-point pair no special protection'  [pure]  @ 590-596

